const fs = require('fs');

// Get GitHub Actions Environment Variables
const repo = process.env.GITHUB_REPOSITORY || 'local/repo';
const branch = process.env.GITHUB_REF_NAME || 'main';
const commit = process.env.GITHUB_SHA || 'unknown';
const runId = process.env.GITHUB_RUN_ID || 'local-run';
const receiverUrl = process.env.RECEIVER_URL;

if (!receiverUrl) {
    console.error("Error: RECEIVER_URL is not set.");
    process.exit(1);
}

// Read the JSON test results generated by Jest
let results = {};
try {
    const data = fs.readFileSync('results.json', 'utf8');
    results = JSON.parse(data);
} catch (e) {
    console.error("Could not read results.json. Tests may have completely crashed.");
    process.exit(1);
}

// Extract individual test names, results, and failure messages
const testDetails = [];
results.testResults.forEach(suite => {
    suite.assertionResults.forEach(assertion => {
        testDetails.push({
            name: assertion.title,
            result: assertion.status,
            failureMessage: assertion.failureMessages.length > 0 ? assertion.failureMessages.join('\n') : null
        });
    });
});

// Construct the final payload as required by the assignment
const report = {
    repository: repo,
    branch: branch,
    commitSha: commit,
    pipelineRunId: runId,
    timestamp: new Date().toISOString(),
    tests: testDetails,
    counts: {
        total: results.numTotalTests,
        passed: results.numPassedTests,
        failed: results.numFailedTests
    },
    overallStatus: results.success ? 'PASSED' : 'FAILED'
};

// Send it to the local receiver via the tunnel
fetch(receiverUrl + '/report', {
    method: 'POST',
    headers: { 
        'Content-Type': 'application/json',
        'Bypass-Tunnel-Reminder': 'true' 
    },
    body: JSON.stringify(report)
}).then(res => {
    console.log("Report successfully sent to receiver! Status:", res.status);
}).catch(err => {
    console.error("Failed to send report:", err.message);
});


// BONUS: Send Email via Nodemailer
const nodemailer = require('nodemailer');

const emailUser = process.env.EMAIL_USERNAME;
const emailPass = process.env.EMAIL_PASSWORD;
const emailReceiver = process.env.TO_EMAIL;

if (emailUser && emailPass && emailReceiver) {
    const transporter = nodemailer.createTransport({
        service: 'gmail',
        auth: {
            user: emailUser,
            pass: emailPass
        }
    });

    const mailOptions = {
        from: emailUser,
        to: emailReceiver,
        subject: `CI Test Report: ${report.overallStatus} - ${report.repository}`,
        text: `
DevOps Lab Mid - CI Test Report
---------------------------------
Repository: ${report.repository}
Branch: ${report.branch}
Commit SHA: ${report.commitSha}
Pipeline Run ID: ${report.pipelineRunId}
Timestamp: ${report.timestamp}

Overall Status: ${report.overallStatus}
Total Tests: ${report.counts.total}
Passed: ${report.counts.passed}
Failed: ${report.counts.failed}

Test Details:
${report.tests.map(t => `- ${t.name}: ${t.result}${t.failureMessage ? '\n  Error: ' + t.failureMessage : ''}`).join('\n')}
        `
    };

    transporter.sendMail(mailOptions, (error, info) => {
        if (error) {
            console.error("Error sending email:", error);
        } else {
            console.log("Email sent successfully: " + info.response);
        }
    });
} else {
    console.log("Email credentials not found in environment, skipping email.");
}

